using DriveOS.Modules.TrainingDelivery.Domain.Incidents; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.TrainingDelivery.Infrastructure.Persistence.Configurations;
internal sealed class TrainingIncidentParticipantConfiguration : IEntityTypeConfiguration<TrainingIncidentParticipant>{public void Configure(EntityTypeBuilder<TrainingIncidentParticipant>b){b.ToTable("training_incident_participants");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new TrainingIncidentParticipantId(x));b.Property(x=>x.TrainingIncidentId).HasConversion(x=>x.Value,x=>new TrainingIncidentId(x)).IsRequired();b.Property(x=>x.Label).HasMaxLength(200);b.HasIndex(x=>new{x.TrainingIncidentId,x.Type,x.ReferenceId});}}
